CREATE COLUMN TABLE "TEST_AP"."AWMG" ("ID" INTEGER CS_INT NOT NULL , "TemplateID" INTEGER CS_INT, "TmplateKey" NVARCHAR(254), "Name" NVARCHAR(254), "Version" NVARCHAR(13), "MAXIns" INTEGER CS_INT, "Status" NVARCHAR(1) DEFAULT 'I', "XMLFile" BLOB MEMORY THRESHOLD 1000, "Desc" NCLOB MEMORY THRESHOLD 1000, "LogIns" INTEGER CS_INT NOT NULL , "StartType" NVARCHAR(1) DEFAULT 'M', PRIMARY KEY ("ID", "LogIns")) UNLOAD PRIORITY 5  AUTO MERGE 